# This formula is regenerated by the ankra-cli release workflow from
# packaging/homebrew/ankra.rb.tmpl in ankraio/ankra-cli. Manual edits here
# will be overwritten on the next release; change the template instead.
#
# There is deliberately no `version` stanza: `brew audit` fails a tap whose
# declared version it can already scan from the stable URL (redundant_version),
# and every release URL below carries the tag. That is why the URLs interpolate
# nothing - the release workflow substitutes the version into them directly.
class Ankra < Formula
  desc "Command-line interface for the Ankra Kubernetes platform"
  homepage "https://ankra.io"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.64.0/ankra-cli-darwin-arm64"
      sha256 "c526b18c92e518615c7cb6fd0e457ef0c6a467bcbad7933ebc78e650e24a9c57"
    end
    on_intel do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.64.0/ankra-cli-darwin-amd64"
      sha256 "2160d5375848237b2f1db8a62b3c5716c6b61b24c0aa06dfc376ba233a90b98b"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/ankraio/ankra-cli/releases/download/v0.64.0/ankra-cli-linux-arm64"
      sha256 "ca25a91a8cb3759c7f277616fa1d056ad3f4b994465b070ee351dbcfee5407ca"
    end
    on_intel do
